package com.coworkhub.controller;
import com.coworkhub.entity.*;import com.coworkhub.repository.*;import com.coworkhub.service.CatalogBusinessService;import org.springframework.web.bind.annotation.*;import org.springframework.security.access.prepost.PreAuthorize;import java.util.*;
@RestController @RequestMapping("/api") public class CatalogController {
 private final CatalogBusinessService catalog;private final LocationRepository locations;private final RoomRepository rooms;private final EquipmentRepository equipment;private final MembershipPlanRepository plans;private final AdditionalServiceRepository services;
 public CatalogController(CatalogBusinessService c,LocationRepository l,RoomRepository r,EquipmentRepository e,MembershipPlanRepository p,AdditionalServiceRepository s){catalog=c;locations=l;rooms=r;equipment=e;plans=p;services=s;}
 @GetMapping("/sedes")public List<Location> locations(){return catalog.locations();}@GetMapping("/sedes/{id}")public Location location(@PathVariable Long id){return locations.findById(id).orElseThrow();}@PostMapping("/sedes")@PreAuthorize("hasRole('ADMIN')")public Location addLocation(@jakarta.validation.Valid @RequestBody Location x){x.id=null;return locations.save(x);}@PutMapping("/sedes/{id}")@PreAuthorize("hasRole('ADMIN')")public Location updateLocation(@PathVariable Long id,@jakarta.validation.Valid @RequestBody Location x){Location old=locations.findById(id).orElseThrow();old.name=x.name;old.city=x.city;old.address=x.address;old.openingTime=x.openingTime;old.closingTime=x.closingTime;return locations.save(old);}@DeleteMapping("/sedes/{id}")@PreAuthorize("hasRole('ADMIN')")public Map<String,String> deleteLocation(@PathVariable Long id){locations.delete(locations.findById(id).orElseThrow());return Map.of("mensaje","Sede eliminada");}
 @GetMapping("/salas")public List<Room> rooms(@RequestParam(required=false) Long sedeId){return catalog.rooms().stream().filter(r->sedeId==null||Objects.equals(r.location.id,sedeId)).toList();}@GetMapping("/salas/{id}")public Room room(@PathVariable Long id){return rooms.findById(id).orElseThrow();}record RoomInput(@jakarta.validation.constraints.NotBlank String name,@jakarta.validation.constraints.NotNull Enums.RoomType type,@jakarta.validation.constraints.Positive int capacity,@jakarta.validation.constraints.NotNull @jakarta.validation.constraints.PositiveOrZero java.math.BigDecimal hourlyRate,boolean active,@jakarta.validation.constraints.NotNull Long locationId,List<Long> equipmentIds){}@PostMapping("/salas")@PreAuthorize("hasRole('ADMIN')")public Room addRoom(@jakarta.validation.Valid @RequestBody RoomInput x){Room r=new Room();applyRoom(r,x);return rooms.save(r);}@PutMapping("/salas/{id}")@PreAuthorize("hasRole('ADMIN')")public Room updateRoom(@PathVariable Long id,@jakarta.validation.Valid @RequestBody RoomInput x){Room r=rooms.findById(id).orElseThrow();applyRoom(r,x);return rooms.save(r);}private void applyRoom(Room r,RoomInput x){r.name=x.name();r.type=x.type();r.capacity=x.capacity();r.hourlyRate=x.hourlyRate();r.active=x.active();r.location=locations.findById(x.locationId()).orElseThrow();r.equipment=new HashSet<>(equipment.findAllById(x.equipmentIds()==null?List.of():x.equipmentIds()));}@DeleteMapping("/salas/{id}")@PreAuthorize("hasRole('ADMIN')")public Map<String,String> deleteRoom(@PathVariable Long id){rooms.delete(rooms.findById(id).orElseThrow());return Map.of("mensaje","Sala eliminada");}
 @GetMapping("/equipamientos")public List<Equipment> equipments(){return catalog.equipment();}@GetMapping("/equipamientos/{id}")public Equipment equipment(@PathVariable Long id){return equipment.findById(id).orElseThrow();}@PostMapping("/equipamientos")@PreAuthorize("hasRole('ADMIN')")public Equipment addEquipment(@jakarta.validation.Valid @RequestBody Equipment x){x.id=null;return equipment.save(x);}@PutMapping("/equipamientos/{id}")@PreAuthorize("hasRole('ADMIN')")public Equipment updateEquipment(@PathVariable Long id,@jakarta.validation.Valid @RequestBody Equipment x){Equipment e=equipment.findById(id).orElseThrow();e.name=x.name;return equipment.save(e);}@DeleteMapping("/equipamientos/{id}")@PreAuthorize("hasRole('ADMIN')")public Map<String,String> deleteEquipment(@PathVariable Long id){equipment.delete(equipment.findById(id).orElseThrow());return Map.of("mensaje","Equipamiento eliminado");}
 @GetMapping("/planes")public List<MembershipPlan> plans(){return catalog.plans();}@GetMapping("/planes/{id}")public MembershipPlan plan(@PathVariable Long id){return plans.findById(id).orElseThrow();}@PostMapping("/planes")@PreAuthorize("hasRole('ADMIN')")public MembershipPlan addPlan(@jakarta.validation.Valid @RequestBody MembershipPlan x){x.id=null;return plans.save(x);}@PutMapping("/planes/{id}")@PreAuthorize("hasRole('ADMIN')")public MembershipPlan updatePlan(@PathVariable Long id,@jakarta.validation.Valid @RequestBody MembershipPlan x){MembershipPlan p=plans.findById(id).orElseThrow();p.name=x.name;p.includedHoursPerMonth=x.includedHoursPerMonth;p.overageDiscount=x.overageDiscount;p.maxActiveBookings=x.maxActiveBookings;return plans.save(p);}@DeleteMapping("/planes/{id}")@PreAuthorize("hasRole('ADMIN')")public Map<String,String> deletePlan(@PathVariable Long id){plans.delete(plans.findById(id).orElseThrow());return Map.of("mensaje","Plan eliminado");}
 @GetMapping("/servicios-adicionales")public List<AdditionalService> services(){return catalog.additionalServices();}@GetMapping("/servicios-adicionales/{id}")public AdditionalService service(@PathVariable Long id){return services.findById(id).orElseThrow();}@PostMapping("/servicios-adicionales")@PreAuthorize("hasRole('ADMIN')")public AdditionalService addService(@jakarta.validation.Valid @RequestBody AdditionalService x){x.id=null;return services.save(x);}@PutMapping("/servicios-adicionales/{id}")@PreAuthorize("hasRole('ADMIN')")public AdditionalService updateService(@PathVariable Long id,@jakarta.validation.Valid @RequestBody AdditionalService x){AdditionalService s=services.findById(id).orElseThrow();s.name=x.name;s.unitPrice=x.unitPrice;return services.save(s);}@DeleteMapping("/servicios-adicionales/{id}")@PreAuthorize("hasRole('ADMIN')")public Map<String,String> deleteService(@PathVariable Long id){services.delete(services.findById(id).orElseThrow());return Map.of("mensaje","Servicio eliminado");}
}
